```css
.chapter-content {
  min-width: 0;
  max-width: 100%;
  color: var(--text);
  font-family: var(--reader-font);
  font-size: var(--reader-size);
  line-height: var(--reader-leading);
  line-break: strict;
  word-break: normal;
  overflow-wrap: break-word;
  text-spacing-trim: trim-start;
}
.chapter-content .chapter-title {
  margin: 0 0 24px;
  font-size: 1.6em;
  font-weight: 600;
  line-height: 1.25;
  text-align: center;
  text-indent: 0;
  break-after: avoid;
}
.chapter-content p {
  margin: 0;
  text-indent: 2em;
  text-align: justify;
  line-break: strict;
  word-break: normal;
  overflow-wrap: break-word;
  text-spacing-trim: trim-start;
  line-height: var(--reader-leading);
  orphans: 2;
  widows: 2;
}
.chapter-content .dateline,
.chapter-content .scene-break {
  margin: 24px 0;
  color: var(--muted);
  text-align: center;
  text-indent: 0;
}
.chapter-content .dateline {
  margin-top: 0;
  font-size: 0.85em;
}
.chapter-content hr.rule {
  width: 32%;
  margin: 32px auto;
  border: 0;
  border-top: 1px solid var(--border);
}
.chapter-content blockquote {
  margin: 24px 0;
  padding-inline: 20px;
  border-inline-start: 3px solid var(--border);
}
.chapter-content .dialog { padding-block: 4px; }
.chapter-content .dialog.railed {
  border-inline-start: 3px solid currentColor;
  padding-inline-start: 16px;
}
.chapter-content ul,
.chapter-content ol {
  margin-block: 16px;
  padding-inline-start: 2em;
}
.chapter-content li {
  padding-inline-start: 4px;
  text-indent: 0;
}
.chapter-content li + li { margin-top: 4px; }
.chapter-content sup,
.chapter-content sub {
  position: relative;
  font-size: 0.7em;
  line-height: 0;
  vertical-align: baseline;
}
.chapter-content sup { top: -0.5em; }
.chapter-content sub { bottom: -0.2em; }
.chapter-content code {
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 0.9em;
  overflow-wrap: anywhere;
}
.chapter-content b,
.chapter-content strong { font-weight: 700; }
.chapter-content em { font-style: italic; }
.chapter-content figure.fig {
  box-sizing: border-box;
  max-width: 100%;
  margin: 24px auto;
  padding: 8px;
  overflow: auto;
  border-radius: var(--figure-radius);
  background: var(--terminal-bg);
  color: var(--terminal-text);
  text-align: center;
  text-indent: 0;
  break-inside: avoid;
}
.chapter-content figure.fig img {
  display: block;
  max-width: 100%;
  height: auto;
  margin-inline: auto;
  object-fit: contain;
}
.chapter-content figure.fig figcaption {
  padding: 8px 4px 0;
  font: 0.75em/1.5 var(--font-sans);
  text-align: center;
}
.device-view {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  margin: 24px auto;
  padding: 16px;
  overflow-x: auto;
  border-radius: var(--radius);
  background: var(--terminal-bg);
  color: var(--terminal-text);
  color-scheme: dark;
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 0.85em;
  line-height: 1.7;
  text-align: start;
  text-indent: 0;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--terminal-text) var(--terminal-bg);
  break-inside: avoid;
}
.wide-device-view { width: 100%; }
.device-view-left { margin-inline: 0 auto; text-align: start; }
.chapter-content .device-view p {
  text-indent: 0;
  text-align: start;
  line-height: inherit;
}
.device-view table {
  width: 100%;
  border-collapse: collapse;
  font: inherit;
  text-align: start;
}
.device-view th,
.device-view td {
  padding: 8px 12px;
  border: 1px solid var(--terminal-text);
  text-align: start;
  vertical-align: top;
  overflow-wrap: anywhere;
}
.device-view thead {
  background: var(--terminal-text);
  color: var(--terminal-bg);
}
.device-view input[type="range"] {
  box-sizing: border-box;
  display: block;
  width: 100%;
  min-width: 0;
